export function checkManifest(crossed){const set=new Set(crossed);return [0,1,2].map(group=>LOT_ITEMS.slice(group*4,group*4+4).some(a=>set.has(a.id)===a.keep));}
export function manifestCorrect(crossed){return checkManifest(crossed).every(v=>!v);}
