for(let i=0;i<REFERENCES.length;i++){const r=REFERENCES[i];EXPANSION_WORKS['reference'+i]={title:r.title,artist:'Collection study · '+r.year,meta:r.medium+' · reference '+String.fromCharCode(65+i),text:r.items.map(id=>{const a=LOT_ITEMS[id-1];return String(id).padStart(2,'0')+' / '+a.name+'\n'+a.record;}).join('\n\n')};}
